    LANGUAGE sql STABLE
    AS $$
    SELECT 
        o.id, o.order_number, o.tenant_id, o.organization_id, o.branch_id, o.classroom_id,
        o.planned_experience_id, o.requesting_user_id, o.requesting_user_email,
