CREATE PROCEDURE public.sp_delete_branch(IN p_tenant_id uuid, IN p_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM branches
    WHERE id = p_id AND tenant_id = p_tenant_id;
END;
$$;


