    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO classroom_teachers (id, tenant_id, classroom_id, user_id, is_primary)
    VALUES (gen_random_uuid(), p_tenant_id, p_classroom_id, p_user_id, FALSE)
    ON CONFLICT (classroom_id, user_id) DO NOTHING;
END;
$$;


