COPY public.experiences (id, tenant_id, title, description, status, dna_payload, created_by_user_id, created_at, updated_at, organization_id) FROM stdin;
60000000-0000-0000-0000-000000000003	10000000-0000-0000-0000-000000000001	Leaping Lily Pad Math Quest (Focus: Make It More Playful)	Children decorate pre-folded leaping origami paper frogs and practice finger pressure control to make them leap across numbered lily pads. Adapted with emphasis on: Make it more playful.	Published	{"AgeMax": 4, "AgeMin": 2, "Create": "A custom origami frog and a lily pad target course marked with numbers and colors.", "Together": "We decorate our paper frogs with colorful patterns and test how pressing the back of the frog makes it launch into the air.", "Challenge": "Can you make your paper frog jump from lily pad to lily pad to reach the big pond? Challenge adaptation: Make it more playful.", "Materials": ["Pre-cut square paper (green, yellow, light blue)", "Pre-folded paper jumping frogs", "Green foam or felt lily pads cutouts with numbers 1-5", "Washable markers", "Googly eyes and glue dots", "Large blue floor mat or blue fabric sheet"], "Reflection": "How did your frog move differently when you pressed softly compared to when you pressed hard?", "ChildChoice": "Children choose their frog color, decorative stickers, and which numbered path to leap along.", "Environment": "Indoor / Outdoor", "MagicMoment": "The exciting instant the paper frog launches into the air and lands right on a green lily pad.", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Mastering the finger tap technique to send the paper frog leaping accurately onto a target.", "ExecutionGuide": {"Ask": "What happens when you press the back of the frog very quickly? Which lily pad is your frog aiming for next?", "Try": "If a child struggles to make the frog leap, place your finger over theirs to guide the downward slide release motion.", "Watch": "Observe how children adjust their finger pressure and fine motor precision when trying to launch the frog.", "Phases": [{"Name": "Frog Personalization", "ChildrenDo": "Decorate pre-folded paper frogs using markers, dots, and googly eyes.", "TeacherDoes": "Demonstrate how to stick googly eyes on the front and praise unique color choices.", "DurationMinutes": 8}, {"Name": "Launch Practice", "ChildrenDo": "Practice pressing down on the rear spring fold of the frog using one finger to make it launch.", "TeacherDoes": "Guide children's finger placement on the back fold. Model light versus firm pressure.", "DurationMinutes": 5}, {"Name": "Lily Pad Hop Game", "ChildrenDo": "Launch frogs along the numbered lily pad paths, calling out the numbers as frogs land on them.", "TeacherDoes": "Encourage children to aim for specific numbers and celebrate every successful jump.", "DurationMinutes": 10}, {"Name": "Tidy & Group Reflection", "ChildrenDo": "Gather paper frogs and collect lily pads into the storage basket.", "TeacherDoes": "Lead a brief cool-down transition chant about sleepy frogs resting in the pond.", "DurationMinutes": 2}], "Safety": ["Ensure children keep small googly eyes away from their mouths.", "Keep the jumping area clear of foot traffic to prevent tripping."], "Closing": "Place all the paper frogs together on the large center lily pad for a quick group photo before transition.", "Extensions": ["Add a tape measure to compare which frog jumped the longest distance.", "Introduce addition by adding up the numbers on the lily pads where the frog lands."], "Adaptations": ["Provide larger pre-folded frogs made of thick paper for children needing bigger motor targets.", "Draw visual directional arrows on the lily pads to assist visual learners."], "Preparation": ["Pre-fold 2-3 origami jumping frogs per child using sturdy cardstock or origami paper.", "Cut out 10-15 green felt circles to serve as lily pads and write numbers 1 to 5 on them.", "Spread the blue fabric sheet on the floor to represent the pond."], "MaterialSetup": ["Place blank origami frogs, markers, googly eyes, and glue dots at tables.", "Set the pre-folded blank frogs in small trays for easy access."], "EnvironmentSetup": ["Clear a wide floor space around the blue fabric pond.", "Arrange lily pads in linear paths leading toward the center of the pond."], "TeacherIntroduction": "Look at these amazing paper frogs! When we press down gently on their backs, they hop high into the air. Let's make our own frogs and help them leap across the lily pads!", "LittleMomentOpportunity": "A quiet moment occurs when a child gently places their finger on the frog, takes a focused breath, and watches it flip successfully.", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Focus on the physical mechanics of pressing down on the spring-fold. Pre-fold the frogs so children can focus on decorating and playing without frustration.", "DevelopmentalGoals": []}	50000000-0000-0000-0000-000000000001	2026-09-25 00:09:42.531981+00	2026-10-15 00:17:47.520163+00	20000000-0000-0000-0000-000000000001
8418a6dc-5770-4e75-afc5-c1fb2711a448	10000000-0000-0000-0000-000000000001	The Magical Animal Dance Party!	An active, highly playful music and movement adventure where children use colorful ribbon wands and balloons to dance like magical animals and play a thrilling freeze-dance game.	Published	{"AgeMax": 5, "AgeMin": 3, "Create": "Children will dance dynamically with ribbon wands and balloons, matching their body movements to fast, slow, and silly music tempos.", "Together": "We will gather in a circle, shake out our 'silly bones' together, and practice making giant wind spirals in the air using our colorful ribbon wands.", "Challenge": "Can you keep your balloon buddy floating in the air using only your elbows, knees, or your colorful ribbon wand while the music plays?", "Materials": ["Colorful ribbon wands (one per child)", "Inflated colorful balloons (plus 3-4 spares)", "Music player with pre-selected fast, slow, and silly instrumental tracks"], "Reflection": "Which animal dance made you laugh the most? How did your ribbon wand move when the music got super-fast?", "ChildChoice": "Children choose their ribbon wand color, their balloon buddy, and get to invent their own silly animal dance move for the whole class to copy.", "Environment": "Indoor / Outdoor", "MagicMoment": "The 'Freeze-Dance Balloon Catch' where the music suddenly stops and everyone must instantly freeze while balancing their balloon on a silly body part, like their head or nose!", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "We successfully guided our balloon buddies through the magical dance forest and celebrated with a grand finale dance explosion!", "ExecutionGuide": {"Ask": "Ask: 'How does a giant, heavy dinosaur dance compared to a tiny, bouncy frog? Can you show me with your ribbon wand?'", "Try": "Try prompting the children to tap their balloons using only their elbows, shoulders, or heads to ramp up the physical comedy and laughter.", "Watch": "Watch for children who get overstimulated or frustrated if their balloon floats away, and step in to gently toss it back into their play space to keep the play joyful.", "Phases": [{"Name": "Silly Bone Warm-Up", "ChildrenDo": "Shake out hands, feet, hips, and noses to silly sound effects, warming up their muscles.", "TeacherDoes": "Leads the movements, calling out funny body parts to shake and making silly vocal sound effects.", "DurationMinutes": 5}, {"Name": "Ribbon Wand Windstorms", "ChildrenDo": "Select a ribbon wand, space out, and paint the air with giant loops, circles, and zig-zags matching the speed of the music.", "TeacherDoes": "Changes the music speed and narrates the play: 'Oh, now we are slow-motion sloths! Now we are speedy cheetahs!'", "DurationMinutes": 7}, {"Name": "Balloon Buddy Freeze Dance", "ChildrenDo": "Receive a balloon, tap it gently into the air to keep it up, and instantly freeze in a silly pose when the music stops.", "TeacherDoes": "Controls the music, calls out wacky freeze challenges like 'Freeze and balance your balloon on your knee!'", "DurationMinutes": 10}, {"Name": "The Balloon Pop Cool-Down", "ChildrenDo": "Pretend to be balloons inflating with a deep breath, then slowly hiss and melt all the way down to the floor like deflating balloons.", "TeacherDoes": "Guides deep breathing exercises with visual balloon analogies to transition children back to a calm state.", "DurationMinutes": 3}], "Safety": ["Actively monitor for popped balloon pieces and immediately discard them to prevent choking hazards.", "Ensure children maintain a safe bubble of space around themselves to avoid ribbon wands hitting peers."], "Closing": "Give your balloon buddy a gentle high-five, put your ribbon wands back in the sleeping basket, and float quietly back to your spots like gentle clouds.", "Extensions": ["Add a bubble machine during the fast-tempo phase to create an extra sensory, magical chasing element to the dance party."], "Adaptations": ["For children with limited mobility, tie a balloon to their wrist with a soft yarn strand so they can easily participate in keeping it afloat from a seated position."], "Preparation": ["Inflate all balloons before the children arrive.", "Set up a playlist with clear shifts between fast tempos, slow tempos, and sudden pauses."], "MaterialSetup": ["Place ribbon wands in a basket on one side of the room.", "Keep the inflated balloons hidden inside a large bag or net to reveal as a exciting surprise."], "EnvironmentSetup": ["Clear a large, open floor space free of tables, chairs, and tripping hazards."], "TeacherIntroduction": "Welcome to the Magical Dance Forest, explorers! Today our bodies are turning into silly, dancing animals. Look what I have in my magic basket to help us dance!", "LittleMomentOpportunity": "Catch a child giggling while intensely concentrating on balancing a balloon on their forehead, and mimic their pose to share a joyful, silent connection.", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Keep your energy high, warm, and highly playful! Model goofy, exaggerated movements to show children it is safe to be silly. Use suspenseful pauses when stopping the music to keep engagement locked in.", "DevelopmentalGoals": []}	50000000-0000-0000-0000-000000000001	2026-09-25 02:31:46.38199+00	2026-10-09 15:17:47.996038+00	20000000-0000-0000-0000-000000000001
60000000-0000-0000-0000-000000000004	10000000-0000-0000-0000-000000000001	Secret Safari Sound Parade	Children step into the role of Safari Sound Detectives, pulling secret animal performers from a mysterious safari trunk and enacting dramatic sound clues for their friends to decode before leading a hilarious group animal parade.	Published	{"AgeMax": 4, "AgeMin": 2, "Create": "A dynamic pretend-play experience packed with dramatic vocal effects, animated guessing moments, and energetic group movement.", "Together": "Join forces as a detective crew to crack sound codes, celebrate each correct guess, and leap into action together for an enthusiastic group animal parade.", "Challenge": "Can you transform into a secret creature using vocal clues and dramatic body poses so your fellow sound detectives can guess who you are?", "Materials": ["1 Opaque 'Safari Trunk' (decorated box or soft fabric bag)", "12-15 Toy animals (mix of jungle, farm, and ocean creatures)", "1 Pair of toy paper-tube binoculars per child", "1 Playful Safari Ranger hat or badge for the leader"], "Reflection": "Which animal sound was the most fun to make? How did changing our voices make us feel like gigantic giants or tiny creatures?", "ChildChoice": "Children select their secret animal figure, choose their vocal pitch and volume, and decide on a custom action pose for the big reveal.", "Environment": "Indoor / Outdoor", "MagicMoment": "The burst of joy when a child reveals their mystery animal and the entire class instantly leaps up to mimic the sound and movement in unison.", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Confidently expressing vocal creativity and leading peers in a collaborative, imaginative role-playing adventure.", "ExecutionGuide": {"Ask": "What kind of creature makes a squeaky, high sound like that? Can you show me how a giant creature walks across the jungle?", "Try": "Try inviting the whole group to repeat the sound together in a quiet whisper before making it as grand and loud as possible.", "Watch": "Watch for children using dramatic shifts in pitch, volume, and full-body postures to make their animal clues extra expressive.", "Phases": [{"Name": "Detective Briefing", "ChildrenDo": "Put on paper binoculars, practice deep roars and tiny squeaks, and listen to the activity rules.", "TeacherDoes": "Introduce the pretend safari world, model high and low sound effects, and present the Safari Trunk.", "DurationMinutes": 5}, {"Name": "Secret Sound Clues", "ChildrenDo": "Reach into the trunk without looking, freeze in a secret animal statue pose, and make expressive animal vocalizations.", "TeacherDoes": "Hand the performer the Ranger Badge, prompt fun sound variations, and call on detective peers to guess.", "DurationMinutes": 10}, {"Name": "Grand Safari Parade", "ChildrenDo": "Reveal the hidden toy figure, then jump up with the class to parade around the carpet making the animal sound.", "TeacherDoes": "Lead a celebratory 30-second mini-parade around the circle before returning to basecamp for the next turn.", "DurationMinutes": 10}], "Safety": ["Ensure carpet area is free of loose items during movement phases.", "Remind children to respect personal space while parading around the rug."], "Closing": "Guide all animals back into the Safari Trunk for a restful nap until the next expedition.", "Extensions": ["Create a Safari Sound Map where children draw paths to different animal habitats based on the sounds made during the activity."], "Adaptations": ["Allow shy children to perform alongside a designated 'Co-Ranger' buddy.", "Provide picture cue cards of animal sounds for children who benefit from visual support."], "Preparation": ["Place all toy animal figures inside the opaque Safari Trunk.", "Set out paper-tube binoculars at each spot on the rug.", "Put on the Safari Ranger hat to launch the pretend scenario."], "MaterialSetup": ["Place the closed Safari Trunk in the middle of the circle within easy reach."], "EnvironmentSetup": ["Arrange a open carpet circle called 'Safari Basecamp' with plenty of room for energetic group movement."], "TeacherIntroduction": "Calling all Safari Sound Detectives! Deep inside our magic trunk, secret animals are waiting to start a grand parade. Put on your binoculars and get ready to listen carefully!", "LittleMomentOpportunity": "The delighted giggles when the entire group simultaneously mimics a funny animal call during the parade reveal.", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Keep the energy lively, dramatic, and upbeat! Set up a pretend 'Safari Basecamp' on the rug. Facilitate with playful enthusiasm, encouraging children to use dramatic facial expressions, vocal contrast, and expressive body movements.", "DevelopmentalGoals": []}	50000000-0000-0000-0000-000000000001	2026-09-25 00:09:42.531981+00	2026-10-12 23:26:55.206206+00	20000000-0000-0000-0000-000000000001
60000000-0000-0000-0000-000000000001	10000000-0000-0000-0000-000000000001			Archived	{"AgeMax": 3, "AgeMin": 2, "Create": "", "Together": "", "Challenge": "", "Materials": [], "Reflection": "", "ChildChoice": "", "Environment": "Indoor / Outdoor", "MagicMoment": "", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "", "ExecutionGuide": {"Ask": "", "Try": "", "Watch": "", "Phases": [], "Safety": [], "Closing": "", "Extensions": [], "Adaptations": [], "Preparation": [], "MaterialSetup": [], "EnvironmentSetup": [], "TeacherIntroduction": "", "LittleMomentOpportunity": "", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "", "DevelopmentalGoals": []}	50000000-0000-0000-0000-000000000001	2026-09-25 00:09:42.531981+00	2026-10-15 00:18:32.475001+00	20000000-0000-0000-0000-000000000001
c6544348-31d9-491b-bc55-9020089ce1ad	10000000-0000-0000-0000-000000000001	Splashtastic Color Wizards: The Fizzy Flower Rescue	Children become magical Color Wizards working in pairs to build tall block towers (stems) and bring giant coffee-filter flowers to life with vibrant, fizzy watercolor potions!	Published	{"AgeMax": 5, "AgeMin": 3, "Create": "A collaborative 3D flower garden featuring block towers topped with beautifully blended, fizzy watercolor coffee-filter flowers.", "Together": "Working in wizard duos to co-construct block towers, share magic potion cups, and take turns dripping vibrant colors.", "Challenge": "Can you and your partner build a sturdy block tower and splash magic colors to make your flower bloom?", "Materials": ["Wooden building blocks", "Coffee filters cut into flower shapes", "Pipettes or eye droppers", "Vibrant liquid watercolors (Red, Blue, Yellow)", "Baking soda (sprinkled lightly on filters for fizz)", "White vinegar (mixed with watercolors in cups)", "Water trays or plastic trays (to catch drips)", "Plastic cups"], "Reflection": "Giggling together while sharing what their magic flowers smell or feel like, and celebrating how they helped each other build the tallest towers.", "ChildChoice": "Choosing block shapes, selecting and mixing custom potion colors, and deciding whether to drip, splash, or fizz their flowers using pipettes or spray bottles.", "Environment": "Indoor / Outdoor", "MagicMoment": "The eyes-wide-open wonder when the bright watercolors hit the coffee filters on top of their towers, spreading and blending like real blooming magic!", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Standing back to admire a giant, shared 3D fantasy garden created through teamwork, laughter, and messy exploration.", "ExecutionGuide": {"Ask": "What kind of magic powers does your orange and purple flower have, and how did you and your partner invent that color?", "Try": "If a child is hesitant to touch the wet filters, try giving them a plastic spray bottle or a paintbrush to apply the potion from a comfortable distance.", "Watch": "Watch how children negotiate sharing the pipettes and blocks, and look for moments of shared joy when the fizzy chemical reaction occurs.", "Phases": [{"Name": "The Wizard Alliance", "ChildrenDo": "Find a wizard partner, choose their magical building blocks, and cooperatively build a tower 'stem' inside their tray.", "TeacherDoes": "Guides children into pairs using fun wizard pairing games, hands out blocks, and prompts them to design strong towers together.", "DurationMinutes": 5}, {"Name": "Potion Brewing & Blooming", "ChildrenDo": "Carefully place their coffee-filter flower on top of their block tower. Use pipettes to collect 'magic potion' (colored vinegar) and drip it onto the flower, watching it fizz and blend.", "TeacherDoes": "Enthusiastically narrates the chemical reactions ('Look at that fizz!'), encourages children to share colors, and helps stabilize towers if they wobble.", "DurationMinutes": 12}, {"Name": "The Giant Garden Tour", "ChildrenDo": "Walk around the room with their partner, admiring other wizards' creations, and sharing how they made their colors.", "TeacherDoes": "Leads a playful 'garden walk', pointing out the unique colors, structures, and collaborative efforts of each duo.", "DurationMinutes": 4}, {"Name": "Wizard Cleanup Play", "ChildrenDo": "Use sponges to 'suck up' leftover magic potion from the trays, squeezing it into a central bucket, and helping stack the blocks.", "TeacherDoes": "Turns cleanup into a game of 'Magic Sponge Tag' to keep the playful energy alive while tidying up.", "DurationMinutes": 4}], "Safety": ["Ensure children do not rub eyes after touching the vinegar/baking soda mixtures.", "Keep towels nearby to quickly wipe up any wet spills on the floor to prevent slipping."], "Closing": "Fantastic wizardry, everyone! Our magic garden is fully charged with color! Wave your hands and say: 'Hocus Pocus, fizzy-flow, watch our beautiful garden glow!'", "Extensions": ["Once dry, tape the colorful coffee-filter flowers to the classroom windows to create a 'stained-glass magic garden' that glows in the sunlight."], "Adaptations": ["For children with fine-motor challenges, swap the small pipettes for squeeze bottles or turkey basters which are easier to grasp."], "Preparation": ["Pre-cut coffee filters into fun flower shapes.", "Lightly dust the dry coffee filters with a thin layer of baking soda.", "Mix liquid watercolors with a splash of white vinegar in plastic cups (this creates the fizzy magic reaction)."], "MaterialSetup": ["Place baskets of blocks near the trays.", "Set out pipettes, cups of colorful liquids, and the baking-soda-dusted coffee filter flowers on small trays for each pair."], "EnvironmentSetup": ["Arrange low tables or floor areas with large plastic trays to contain the block building and wet messes.", "Create 'Wizard Potion Stations' where cups of colored vinegar-water are easily accessible."], "TeacherIntroduction": "Welcome, apprentice Color Wizards! Oh no, the forest has lost its sparkle! We need to work in wizarding duos to build giant wooden flower stems and brew magical fizzy potions to make these sleeping flowers bloom again. Are you ready to splash some magic?", "LittleMomentOpportunity": "Catch the moment two children laugh together as their colors bleed into each other on the filter, creating a brand new color they didn't expect.", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Adopt a playful 'Head Wizard' persona! Instead of focusing on neatness, encourage mess, experimentation, and dramatic play. Help partners coordinate by giving them silly cooperative challenges, like 'Can you place a block at the exact same time?' or 'Mix your potions together to see what new magic you create!'"}	df5d8828-f7cb-4250-9cd1-dba1d787d531	2026-10-05 02:16:53.295997+00	2026-10-07 21:32:39.161878+00	20000000-0000-0000-0000-000000000001
8d740721-0034-4c62-8ba4-94977339ab10	10000000-0000-0000-0000-000000000001	New Experience		Archived	{"AgeMax": 5, "AgeMin": 3, "Create": "", "Together": "", "Challenge": "", "Materials": ["Blocks", "Paper", "Cups", "Water tray"], "Reflection": "", "ChildChoice": "", "Environment": "Indoor / Outdoor", "MagicMoment": "", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "", "ExecutionGuide": {"Ask": "", "Try": "", "Watch": "", "Phases": [{"Name": "New Phasev", "ChildrenDo": "", "TeacherDoes": "", "DurationMinutes": 5}, {"Name": "New Phase", "ChildrenDo": "", "TeacherDoes": "", "DurationMinutes": 5}], "Safety": [], "Closing": "", "Extensions": [], "Adaptations": [], "Preparation": [], "MaterialSetup": [], "EnvironmentSetup": [], "TeacherIntroduction": "", "LittleMomentOpportunity": "", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "", "DevelopmentalGoals": []}	df5d8828-f7cb-4250-9cd1-dba1d787d531	2026-10-09 15:29:44.360524+00	2026-10-09 15:30:04.643269+00	20000000-0000-0000-0000-000000000001
025724ee-46ad-4f3e-b37a-c573ecada70d	10000000-0000-0000-0000-000000000001	Silly Splash Island Water Park	A playful water-building adventure where children construct silly islands, wild water slides, and floating splash-zones for toy characters using cups, blocks, and water.	Archived	{"AgeMax": 5, "AgeMin": 3, "Create": "Children build splash zones! They stack cups to make water towers, line up blocks as slippery slides, and float cup-boats, letting their toy animals dive, slide, and splash into the water.", "Together": "We gather around the water tray. The teacher introduces some silly toy animals who 'really want to go swimming!' We practice making our best splashing sounds (Whoosh! Splash!) and talk about what rides we want to build for them.", "Challenge": "Can you build a silly splash park with slides, pools, or boats for your toy friends to play on?", "Materials": ["Water tray filled halfway", "Plastic or foam building blocks", "Plastic cups (various sizes)", "Small plastic toy animals or characters", "Sponges and small pitchers for pouring"], "Reflection": "Ask the children: 'What was your toy's favorite ride today? Who made the loudest splash sound? What should we build for our next water park adventure?'", "ChildChoice": "Children choose which toy animal to play with, whether to build a tall slide or a floating boat, and how much splashing and pouring their toy gets to do.", "Environment": "Indoor / Outdoor", "MagicMoment": "The exact second a child slides a toy animal down a wet block ramp and it lands with a satisfying 'splat!' right inside a floating cup!", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Each child gives their toy animal one giant 'Grand Finale Splash' into their creation while making a loud, silly sound effect!", "ExecutionGuide": {"Ask": "Ask playful questions: 'Is your toy going down the fast slide or taking a relaxing cup-bath? Can we make a rainstorm with this sponge to fill your pool?'", "Try": "Try adding a playful twist if a child is stuck: 'Oh look, this little frog is looking for a floating island! Can you build him a boat using a cup and a block?'", "Watch": "Watch for dramatic play narratives. Note how children use the physical properties of water (buoyancy, pouring, sliding) to fuel their imaginative scenarios with the toys.", "Phases": [{"Name": "Meet the Swimmers", "ChildrenDo": "Choose a toy animal, test how it floats, and splash it in the water while making funny animal noises.", "TeacherDoes": "Hand out toys, encourage silly swimming sounds, and ask children what kind of water ride their toy wants.", "DurationMinutes": 5}, {"Name": "Build the Wild Rides", "ChildrenDo": "Stack blocks to make slides, float cups as hot tubs, and use sponges to rain water down on their toys.", "TeacherDoes": "Playfully narrate the building: 'Wow, Leo's dinosaur is climbing a giant block tower! Look at that splash!'", "DurationMinutes": 12}, {"Name": "The Grand Splash Show", "ChildrenDo": "Show off their favorite ride by sending their toy down the slide or into the pool with a big collective splash.", "TeacherDoes": "Cheer, countdown '3-2-1 Splash!', and celebrate everyone's silly ideas.", "DurationMinutes": 5}, {"Name": "Splash-Free Cleanup", "ChildrenDo": "Squeeze water out of sponges, load toys and blocks into drying baskets, and dry their hands.", "TeacherDoes": "Make cleanup a game by asking children to rescue the toys from the water and tuck them into dry towel beds.", "DurationMinutes": 3}, {"Name": "New Phase", "ChildrenDo": "", "TeacherDoes": "", "DurationMinutes": 5}], "Safety": ["Keep the floor dry by having sponges ready to soak up spills.", "Remind children to keep splashing gentle and inside the water tray area."], "Closing": "You built the best water park ever! Our toy friends are so happy and tired from all the sliding and splashing. High-fives for our silly builders!", "Extensions": ["Add plastic funnels or bendy straws to create 'water pipes' and secret slides.", "Give children washable markers to draw swimsuits on plastic toys before they dive in."], "Adaptations": ["For children who dislike getting wet, let them build a dry block-tower 'viewing deck' next to the water for their toy.", "For extra sensory fun, add bubble bath to the water tray for a soapy splash park."], "Preparation": ["Fill the water tray halfway with warm water.", "Gather a basket of plastic blocks, cups, and toy animals next to the tray."], "MaterialSetup": ["Drop a few cups and toys directly in the water to invite immediate play.", "Keep blocks and sponges dry in baskets nearby so kids can choose when to wet them."], "EnvironmentSetup": ["Place the water tray in an easy-to-reach spot.", "Lay down towels or a plastic splash mat underneath to catch wild splashes."], "TeacherIntroduction": "Oh no! Our toy animal friends are so hot and want to go to a wild water park! But there are no rides yet! Can you help me build the silliest splash islands, slides, and pools ever? Let's make some waves!", "LittleMomentOpportunity": "When a child naturally starts making their toy talk or slide down a block, lean in and pretend to be a customer waiting in line for their amazing ride!", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Keep the energy light and joyful. Act as the play coordinator—narrate the toys' adventures with fun sound effects (Wheee! Splash!) and encourage silly ways to move water, like pouring from high up or making mini waves.", "DevelopmentalGoals": []}	df5d8828-f7cb-4250-9cd1-dba1d787d531	2026-10-07 22:13:14.698792+00	2026-10-09 15:09:06.114247+00	20000000-0000-0000-0000-000000000001
60000000-0000-0000-0000-000000000002	10000000-0000-0000-0000-000000000001			Archived	{"AgeMax": 5, "AgeMin": 3, "Create": "", "Together": "", "Challenge": "", "Materials": [], "Reflection": "", "ChildChoice": "", "Environment": "Indoor / Outdoor", "MagicMoment": "", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "", "ExecutionGuide": {"Ask": "", "Try": "", "Watch": "", "Phases": [], "Safety": [], "Closing": "", "Extensions": [], "Adaptations": [], "Preparation": [], "MaterialSetup": [], "EnvironmentSetup": [], "TeacherIntroduction": "", "LittleMomentOpportunity": "", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "", "DevelopmentalGoals": []}	50000000-0000-0000-0000-000000000001	2026-09-25 00:09:42.531981+00	2026-10-15 00:18:37.348547+00	20000000-0000-0000-0000-000000000001
954d2948-70d8-4837-aebb-75dd0679591b	10000000-0000-0000-0000-000000000001	The Goofy Fizzy Flower Rescue	Apprentice wizards wear silly hats, chant funny spells, and work in giggly pairs to build wobbly block towers and wake up giant coffee-filter flowers with exploding, fizzing color potions!	Archived	{"AgeMax": 5, "AgeMin": 3, "Create": "A collaborative, colorful 3D garden of giant, fizzing watercolor flowers resting on top of goofy wooden block towers.", "Together": "Working in silly wizard duos, performing secret high-fives, and taking turns dripping color potions to trigger funny fizzing reactions together.", "Challenge": "Can you and your wizard partner build a wacky block tower and make your flower 'gasp' and fizz with magic colors?", "Materials": ["Wooden building blocks", "Coffee filters cut into simple flower shapes", "Baking soda (sprinkled on the dry filters beforehand)", "White vinegar mixed with bright liquid watercolors (Red, Blue, Yellow)", "Pipettes and small squeeze bottles ('Wizard Wands')", "Deep plastic trays or sensory bins (to contain the fizz)", "Silly paper wizard hats or headbands", "Sponges for cleanup play"], "Reflection": "Giggling together as they invent silly names for their new colors (like 'Snotty-Grape-Green' or 'Exploding-Banana-Yellow') and talking about whose tower wobbled the most.", "ChildChoice": "Choosing their own wizard tools (pipettes or squeeze bottles), picking wacky potion colors to mix, and deciding how tall or wobbly to build their block tower.", "Environment": "Indoor / Outdoor", "MagicMoment": "The instant eyes-wide-open laughter when the colored potion hits the baking soda, making a loud 'PSST!' sound as the colors explode and blend.", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Striking a dramatic wizard pose with their partner next to their completed, colorful, fizzing creation while making victory wizard sounds.", "ExecutionGuide": {"Ask": "If your fizzy flower had a funny voice, what would it say to you right now? What silly name should we give this bubbly green color you made?", "Try": "If a child is hesitant to use the pipettes, pretend the pipette is a sleepy baby dragon that needs its tummy squeezed to breathe colored fire.", "Watch": "Watch for kids sharing giggles when the baking soda fizzes, and see how they playfully negotiate which colors to mix together on their shared flower.", "Phases": [{"Name": "Goofy Tower Building", "ChildrenDo": "Put on imaginary (or paper) wizard hats, invent a secret partner handshake, and build a silly, tall block tower inside their tray to act as a flower stem.", "TeacherDoes": "Guides children into pairs. Challenges them with playful prompts like 'Can you build using only your elbows?' or 'Make a funny squeak every time you add a block!'", "DurationMinutes": 6}, {"Name": "The Great Fizzy Tickle!", "ChildrenDo": "Place their coffee-filter flower on top of the tower. Squeeze and drip their colorful potions onto the flower, making loud 'PSST!' and 'FIZZ!' sounds as the color bubbles up and spreads.", "TeacherDoes": "Acts as the hyperactive Head Wizard, walking around to cheer on the bubble explosions and encouraging partners to mix their colors to see what goofy shades they create.", "DurationMinutes": 11}, {"Name": "The Wacky Garden Parade", "ChildrenDo": "March around the room like funny wizards, admiring everyone's fizzing towers and showing off their color blends with silly poses.", "TeacherDoes": "Leads the parade, pointing out the most wobbly towers, the brightest fizzes, and the best cooperative teamwork.", "DurationMinutes": 4}, {"Name": "Sponge Monster Cleanup", "ChildrenDo": "Pretend their sponges are 'Hungry Sponge Monsters' that love to eat colorful puddles, wiping up the trays and squeezing the liquid into a central bucket.", "TeacherDoes": "Makes funny eating noises ('OM NOM NOM!') to turn the cleanup process into a hilarious game.", "DurationMinutes": 4}], "Safety": ["Keep towels nearby for wet floors.", "Remind children to keep the vinegar potion away from their eyes and to wash hands if they get sticky."], "Closing": "Incredible wizarding! You have successfully tickled the flowers awake! Put your hands in the middle with your partner and shout: 'Abracadabra, fizzy-pop-shazam!'", "Extensions": ["Once dry, hang the goofy, colorful flowers on the windows and let the children draw funny monster faces or googly eyes on them with markers."], "Adaptations": ["For younger children or those with fine-motor challenges, swap the small pipettes for larger, easy-to-squeeze plastic condiment bottles."], "Preparation": ["Dust the coffee-filter flowers with a thin layer of baking soda.", "Mix the colored liquid watercolors with white vinegar in small cups.", "Place blocks and trays at each station."], "MaterialSetup": ["Put a basket of blocks, two cups of colored vinegar potion, two pipettes, and two dry baking-soda-dusted flowers inside each tray."], "EnvironmentSetup": ["Set up the plastic trays on the floor or low tables so children can move around freely and play comfortably."], "TeacherIntroduction": "Alakazam, magical friends! The sleeping flowers are feeling super lazy today. We need to team up as Wobbly Wizards, build silly block towers, and tickle these flowers awake with our explosive, fizzy-wuzzy potions! Are you ready to make some magic noise?", "LittleMomentOpportunity": "Capture the exact moment two partners bump heads slightly, laugh, and decide to combine their potions to create a giant, unexpected double-colored bubble explosion.", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Put on a silly hat and fully embrace a goofy 'Head Wizard' persona! Use dramatic voices, encourage the kids to make loud 'WHOOSH' and 'FIZZ' sounds, and focus entirely on the joy of experimentation, mess, and play rather than neatness."}	df5d8828-f7cb-4250-9cd1-dba1d787d531	2026-10-07 21:34:35.264551+00	2026-10-09 15:09:14.142933+00	20000000-0000-0000-0000-000000000001
321e1167-db92-4f4f-b41c-a6430e8b0c64	10000000-0000-0000-0000-000000000001	The Wobbly-Wiggle Rainbow Jungle Party!	An active, high-energy sensory painting adventure where children transform into jungle explorers, guiding toy animals to stomp, slide, splash, and wiggle across a giant floor canvas to build a colorful, noisy, and beautifully messy playground.	Published	{"AgeMax": 5, "AgeMin": 3, "Create": "A massive, vibrant floor mural bursting with overlapping rainbow tracks, silly 'splat' patterns, swirly slide-trails, and sensory textures created entirely by dancing and spinning painted toy animals.", "Together": "A small group of children gather around a giant paper canvas on the floor, giggling as they mimic animal sounds, slide their toys through gooey paint, and cooperate to make their animals play, leap, and dance together.", "Challenge": "Can we help our toy animals do a wobbly-wiggle dance, splash in magical paint puddles, and make the most colorful, noisy jungle playground ever?", "Materials": ["A giant roll of butcher paper (6-8 feet long)", "Painter's tape (to secure paper to the floor)", "Washable tempera paints in bright neon and primary colors", "Shallow trays (labeled as 'Paint Puddles')", "A basket of plastic toy jungle animals (elephants, lions, giraffes, frogs, etc.)", "Silly textured rollers (labeled as 'Slither Rollers')", "Splat sponges shaped like leaves or clouds", "Chubby paintbrushes (labeled as 'Tickle Wands')", "Wet wipes and a shallow tub of soapy water (labeled as the 'Jungle Bath')"], "Reflection": "Whispering or roaring like their animals to share: 'What was your animal's favorite silly move? Who did your animal splash or dance with today?'", "ChildChoice": "Children choose their toy animal avatar, select their favorite 'puddle' colors, invent their animal's signature silly move (like the 'Hippopotamus Hop' or 'Slithery Slide'), and decide which parts of the jungle to explore.", "Environment": "Indoor / Outdoor", "MagicMoment": "When two children bump their painted toy animals together, make a silly 'Boing!' sound effect, and watch in delight as their paint tracks merge into a brand-new swirly color.", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Proudly touring the wild, messy canvas and sharing the imaginary, funny stories of how their animals met, danced, and splashed together.", "ExecutionGuide": {"Ask": "", "Try": "", "Watch": "", "Phases": [], "Safety": [], "Closing": "", "Extensions": [], "Adaptations": [], "Preparation": [], "MaterialSetup": [], "EnvironmentSetup": [], "TeacherIntroduction": "", "LittleMomentOpportunity": "", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Transform into the 'Chief Jungle Guide'! Frame the paint trays as 'magical mud puddles' and the brushes as 'tickle wands'. Instead of giving dry instructions, invite children to make animal noises and physically act out the movements of their toys. Keep the atmosphere dynamic and lighthearted, encouraging children to move around the paper, share paint puddles, and collaborate on silly challenges like 'making a giant rainbow slide.'"}	df5d8828-f7cb-4250-9cd1-dba1d787d531	2026-10-05 02:46:51.686687+00	2026-10-06 00:12:32.910444+00	20000000-0000-0000-0000-000000000001
c3adffbe-8269-4571-8dd8-978dfe4a2b2a	10000000-0000-0000-0000-000000000001	Splash & Slide: The Great Block Race!	Turn classic block play and watercolor into a high-energy, sensory painting game where blocks become colorful 'racers' leaving bright trails on a giant paper track!	Published	{"AgeMax": 5, "AgeMin": 3, "Create": "Dip different block shapes into liquid watercolor cups and slide, stamp, or hop them across giant paper sheets to paint a vibrant, messy raceway.", "Together": "We will gather around a giant paper track, dip our blocks into cups of vibrant watercolor, and race them across the paper to create a collaborative masterpiece!", "Challenge": "Can you make your block slide, stomp, or spin across the paper to leave a colorful rainbow trail?", "Materials": ["Wooden or plastic blocks of various shapes", "Large roll of butcher paper", "Plastic cups", "Water tray or shallow bin", "Liquid watercolor paint (washable, multiple colors)", "Tape", "Towels for easy cleanup"], "Reflection": "Ask the children: 'Which block made the longest slide? How did your hands feel when the blocks got slippery?'", "ChildChoice": "Children choose which block shapes to use (tall cylinders, wide rectangles, etc.), which bright watercolor cups to dip them in, and how their 'racer' moves (sliding, stomping, or spinning).", "Environment": "Indoor / Outdoor", "MagicMoment": "The moment a child zooms their block fast across the paper and watches a long, bright streak of color magically appear behind it like a rocket trail!", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Stepping back together to admire a giant, collaborative roadway covered in colorful block prints, swooping slides, and rainbow textures.", "ExecutionGuide": {"Ask": "What kind of track will your block racer make if it hops like a frog? What happens when your red racer crosses paths with a blue racer?", "Try": "Try sliding your block super fast to make a long streak, then try stomping it slowly like a heavy dinosaur to leave perfect shape stamps on the road.", "Watch": "Watch how children experiment with different surfaces of the blocks (flat faces vs. sharp edges) to create thick or thin painted lines, and how they naturally incorporate imaginative vehicle or animal play.", "Phases": [{"Name": "Meet the Racers", "ChildrenDo": "Choose a block racer, test how it slides on the dry paper, and practice making zooming or stomping sound effects.", "TeacherDoes": "Demonstrate how different shapes slide. Ask children what sounds their blocks make (e.g., 'Does your round block roll or slide?').", "DurationMinutes": 5}, {"Name": "The Rainbow Slide", "ChildrenDo": "Dip the bottom of their blocks into the watercolor cups and slide, stamp, or hop them across the paper track.", "TeacherDoes": "Narrate the action like an enthusiastic sports announcer! 'Look at that green triangle zoom across the finish line! Wow, what a huge red stomp!'", "DurationMinutes": 12}, {"Name": "Splashtown Towers", "ChildrenDo": "Stack their wet, colorful blocks on the paper to build colorful towers, then slide them to wash them off in the water tray.", "TeacherDoes": "Encourage children to stack their blocks to see how the colors mix, then guide them to wash the blocks in clean water and wipe their hands.", "DurationMinutes": 8}], "Safety": ["Ensure any spilled water or paint on the floor is wiped up immediately to prevent slipping.", "Remind children to keep the blocks sliding on the paper and not to throw them."], "Closing": "What an incredible race! Our block racers did an amazing job painting this road. Let's give our blocks a warm, bubbly bath in the sink to clean them up for their next big adventure!", "Extensions": ["Add plastic toy cars or animal figures to roll and stomp alongside the blocks.", "Let the painted paper dry and use it as a custom play-mat for toy cars and blocks the next day."], "Adaptations": ["For children sensitive to wet textures, wrap a thick rubber band around the top of the block so they have a dry handle to grip while dipping.", "For younger toddlers, use extra-large blocks that are easier to grasp with two hands."], "Preparation": ["Tape a long, wide sheet of butcher paper securely to the floor or a low table.", "Fill plastic cups halfway with water and stir in vibrant liquid watercolor paint.", "Place the color-filled cups inside the water tray to catch any splashes and spills."], "MaterialSetup": ["Set the cups of liquid watercolor inside the water tray.", "Keep damp towels nearby for quick hand-wipes during the play."], "EnvironmentSetup": ["Position the water tray in the middle of the taped-down paper so children can easily reach it from all sides.", "Spread a collection of different wooden or plastic blocks around the paper area."], "TeacherIntroduction": "Welcome to the Great Block Race! Today, our blocks are going to become speedy racers. When we dip them into our magic rainbow cups, we can slide, stomp, and splash colorful tracks all over our giant paper road! Are your racers ready?", "LittleMomentOpportunity": "Celebrate when a child discovers they can stamp two different shapes on top of each other to make a new design, cheering for their 'magic shape stamp'!", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Keep the energy high, playful, and dramatic! Treat the blocks like characters ('Here comes speedy Blue Rectangle!'). Encourage children to make sound effects (zoom, splash, stomp) as they paint. Use large butcher paper taped securely to the floor or table to handle the energetic sliding.", "DevelopmentalGoals": []}	df5d8828-f7cb-4250-9cd1-dba1d787d531	2026-10-05 01:38:03.053704+00	2026-10-07 23:29:31.664183+00	20000000-0000-0000-0000-000000000001
